// 显式接近策略只消除原同步争格，不用组件假造战果或捕获银行。
#define main naval_original_occupancy_cases
#include "naval_tactics_test.cpp"
#undef main
#include "resident/domains/military/naval_planning.hpp"
namespace {
// 两船同一狭水道是最小僵持来源；所有船体、兵员和战场仍用原域结构。
struct ApproachFixture:Fixture {
 MilitaryBattleCatalog military;NavalBattlePolicy policy;
 ApproachFixture(){frame.units.erase(frame.units.begin()+1);frame.bindings.erase(frame.bindings.begin()+1);assets.vessels.erase(assets.vessels.begin()+1);assets.fleets[0].assignments.resize(1);frame.units[0].position={0,0};frame.units[1].position={2,0};frame.controller_actor_id.clear();frame.controlled_unit_ids.clear();board.cells.clear();for(Integer q=0;q<5;++q)board.cells.push_back({q,0,"water"});board.spawns={{0,{0,0}},{1,{4,0}}};board.exits=board.spawns;military.battlefields={board};policy.battlefield_id=board.id;}
};
const NavalTacticalOrder& order(const NavalTacticalOrders& rows,const StableId& id){for(const auto& row:rows)if(row.first==id)return row.second;throw std::runtime_error("missing order");}
}
int main(){try{ApproachFixture f;
 auto old=take(make_naval_ai(f.assets,f.catalog,f.policy,f.military,f.frame));check(order(old,"unit0").destination==HexPoint{1,0}&&order(old,"unit2").destination==HexPoint{1,0},"original absent-policy algorithm retains exact head-on contention");auto stalled=take(resolve_naval_maneuvers(f.assets,f.catalog,f.board,f.frame,old));check(stalled.frame.units[0].position==f.frame.units[0].position&&stalled.frame.units[1].position==f.frame.units[1].position&&stalled.boarding_requests.empty(),"original synchronous collision reproduces no boarding without changing original rules");
 auto policy=f.policy;policy.ai_maneuver_policy="alternating_approach_v1";auto plans=take(make_naval_ai(f.assets,f.catalog,policy,f.military,f.frame));check(order(plans,"unit0").destination==HexPoint{1,0}&&order(plans,"unit2").action=="hold","odd round advances only authored priority side");auto moved=take(resolve_naval_maneuvers(f.assets,f.catalog,f.board,f.frame,plans));check(moved.frame.units[0].position==HexPoint{1,0}&&moved.frame.units[1].position==HexPoint{2,0}&&moved.boarding_requests.size()==1,"real unchanged microsteps now reach legal boarding range");check(moved.frame.units[0].fit==f.frame.units[0].fit&&moved.frame.units[1].fit==f.frame.units[1].fit&&f.assets.vessels[0].integrity==80&&f.assets.vessels[0].owner.id=="org0","planning and approach create no casualty damage or asset transfer");
 auto next=f.frame;next.round=2;auto even=take(make_naval_ai(f.assets,f.catalog,policy,f.military,next));check(order(even,"unit0").action=="hold"&&order(even,"unit2").destination==HexPoint{1,0},"next public round reverses priority without new randomness");next=moved.frame;next.round=2;auto adjacent=take(make_naval_ai(f.assets,f.catalog,policy,f.military,next));check(order(adjacent,"unit0").action=="board"&&order(adjacent,"unit2").action=="board","yielding side still fights when already truly adjacent");
 auto controlled=f.frame;controlled.controller_actor_id="captain0";controlled.controlled_unit_ids={"unit0"};auto frozen=take(make_naval_ai(f.assets,f.catalog,policy,f.military,controlled));check(frozen.size()==1&&frozen[0].first=="unit2"&&frozen[0].second.action=="hold","AI never manufactures player intent or reads a pending draft");controlled.plan_submitted=true;check(!make_naval_ai(f.assets,f.catalog,policy,f.military,controlled).ok,"AI cannot recompute after player has submitted the frozen round");
 auto unknown=policy;unknown.ai_maneuver_policy="future";check(!make_naval_ai(f.assets,f.catalog,unknown,f.military,f.frame).ok,"unknown explicit maneuver policy refuses");
 auto stopped=f.assets;stopped.vessels[0].integrity=0;auto disabled=take(make_naval_ai(stopped,f.catalog,policy,f.military,f.frame));check(order(disabled,"unit0").action=="hold","new strategy cannot move a disabled vessel");
 Fixture many;many.frame.controller_actor_id.clear();many.frame.controlled_unit_ids.clear();MilitaryBattleCatalog catalog;catalog.battlefields={many.board};auto multi=policy;multi.battlefield_id=many.board.id;auto together=take(make_naval_ai(many.assets,many.catalog,multi,catalog,many.frame));auto result=take(resolve_naval_maneuvers(many.assets,many.catalog,many.board,many.frame,together));bool blocked=false;for(const auto& e:result.events)blocked=blocked||e.code=="NavalMoveBlocked";check(!blocked,"same-side selected AI paths do not compete for a shared microstep");
 auto repeated=take(make_naval_ai(f.assets,f.catalog,f.policy,f.military,f.frame));check(order(repeated,"unit0").destination==order(old,"unit0").destination&&order(repeated,"unit2").destination==order(old,"unit2").destination,"new policy does not change absent-policy source reconstruction");
 std::cout<<"NAVAL_APPROACH="<<checks<<" FAILURES=0 SCOPE=ORIGINAL_PLANNER_AND_MICROSTEPS WORLD=NOT_TESTED\n";return 0;
 }catch(const std::exception& error){std::cerr<<"NAVAL_APPROACH_FAIL checks="<<checks<<" "<<error.what()<<'\n';return 1;}}
